// The name -> clip table the asset pipeline generates (Data/DA_Sounds).
using System;
using System.Collections.Generic;
using UnityEngine;

namespace Metalization
{
    /// <summary>Name → clip table, generated by the asset pipeline.</summary>
    [CreateAssetMenu(menuName = "Metalization/Sound Library", fileName = "DA_Sounds")]
    public class MetalSoundLibrary : ScriptableObject
    {
        [Serializable]
        public class Entry
        {
            public string name;
            public AudioClip clip;
            [Tooltip("Volume multiplier, for balancing without regenerating the WAVs.")]
            public float volume = 1f;
            public MetalVolume group = MetalVolume.Effects;
        }

        public List<Entry> sounds = new List<Entry>();

        Dictionary<string, Entry> lookup;

        public Entry Find(string name)
        {
            if (lookup == null)
            {
                lookup = new Dictionary<string, Entry>();
                foreach (Entry e in sounds)
                {
                    if (e != null && !string.IsNullOrEmpty(e.name)) lookup[e.name] = e;
                }
            }
            return lookup.TryGetValue(name, out Entry found) ? found : null;
        }
    }
}
